function clone(data) { return JSON.parse(JSON.stringify(data)); }
const sharedSession = window.workspaceSession;
let state;
if (sharedSession) state = clone(sharedSession.state);
else if (window.RECONCILE_TEST_MODE) {
  try { state = JSON.parse(localStorage.getItem('reconcileiq-state')) || clone(seed); } catch { state = clone(seed); }
} else { throw new Error('Sign in before opening the workspace.'); }
let workspaceRevision = sharedSession ? sharedSession.revision : 0;
let savedState = clone(state);
let saving = false;
function customerKey(name) { return String(name).trim().toLowerCase(); }
function initializeCustomerTerms() {
  if (!Array.isArray(state.customerTerms)) state.customerTerms = [];
  state.invoices.forEach(invoice => {
    if (!state.customerTerms.some(term => customerKey(term.customer) === customerKey(invoice.customer))) {
      const legacyDays = Number(invoice.creditDays);
      state.customerTerms.push({customer: invoice.customer, creditDays: Number.isFinite(legacyDays) && legacyDays >= 0 ? legacyDays : 45});
    }
  });
}
function customerCreditDays(customer) {
  const term = state.customerTerms.find(term => customerKey(term.customer) === customerKey(customer));
  return term ? Number(term.creditDays) : 45;
}
initializeCustomerTerms();
state.invoices.forEach(invoice => {
  if (!Number.isFinite(Number(invoice.roundOff))) invoice.roundOff = 0;
});
state.advice.forEach(advice => { if (typeof advice.description !== 'string') advice.description = ''; });
state.debitNotes.forEach(note => {
  if (note.type) return;
  const legacy = String(note.reason || '').toLowerCase();
  note.type = legacy.includes('tax') ? 'TAXD' : legacy.includes('price') ? 'PPV' : legacy.includes('packaging') ? 'PQV' : 'Unknown';
});
if (!sharedSession) persist();
let currentView = 'dashboard';
let invoiceFilter = { search:'', status:'all' };
const app = document.getElementById('app');

async function persist(endpoint = '/api/state') {
  if (!sharedSession) { localStorage.setItem('reconcileiq-state', JSON.stringify(state)); return; }
  if (saving) throw new Error('A save is in progress. Please wait.');
  saving = true;
  const buttons = [...document.querySelectorAll('#modalLayer button, #app button')].map(button=>({button,disabled:button.disabled}));
  buttons.forEach(({button}) => { button.disabled = true; });
  try {
    const result = await window.workspaceAPI(endpoint, endpoint === '/api/state' ? 'PUT' : 'POST', {revision: workspaceRevision, state});
    state = result.state; workspaceRevision = result.revision; savedState = clone(state);
    sharedSession.state = clone(state); sharedSession.revision = workspaceRevision;
  } catch (error) {
    state = clone(savedState);
    if (error.status === 409) {
      const latest = await window.workspaceAPI('/api/state');
      state = latest.state; workspaceRevision = latest.revision; savedState = clone(state);
      render();
    }
    throw error;
  } finally { saving = false; buttons.forEach(({button,disabled}) => { button.disabled = disabled; }); }
}
window.replaceWorkspace = async next => { state = clone(next); await persist('/api/restore'); render(); };
window.refreshWorkspace = async (quiet = false) => {
  if (!sharedSession || saving || !document.getElementById('modalLayer').classList.contains('hidden')) return;
  const latest = await window.workspaceAPI('/api/state');
  if (latest.revision !== workspaceRevision) {
    state = latest.state; workspaceRevision = latest.revision; savedState = clone(state); render();
    if (!quiet) showToast('Workspace updated with the latest shared data.');
  }
};
function sum(arr, fn = x => x) { return arr.reduce((total, item) => total + Number(fn(item) || 0), 0); }
function allocations(invoiceId) {
  const result = { Payment:0, TDS:0, PPV:0, PQV:0, CCOGS:0, TaxD:0 };
  state.advice.filter(a => a.invoice === invoiceId).forEach(a => { if (result[a.type] !== undefined) result[a.type] += +a.amount; });
  return result;
}
function invoiceData(inv) {
  const returns = state.returns.filter(x => x.invoice === inv.id);
  const prices = state.priceReturns.filter(x => x.invoice === inv.id);
  const a = allocations(inv.id);
  const qtyReturn = sum(returns, x => x.amount);
  const priceReturn = sum(prices, x => x.amount);
  const roundOff = Number(inv.roundOff || 0);
  const deducted = qtyReturn + priceReturn + sum(Object.values(a));
  const pending = inv.amount - deducted - roundOff;
  const age = Math.max(0, Math.floor((new Date(today) - new Date(inv.date)) / 86400000));
  const creditDays = customerCreditDays(inv.customer);
  const dueDate = new Date(`${inv.date}T00:00:00`);
  dueDate.setDate(dueDate.getDate() + creditDays);
  const status = pending < -1 ? 'overadjusted' : pending <= 1 ? 'settled' : new Date(`${today}T00:00:00`) > dueDate ? 'overdue' : 'due';
  return { ...inv, qtyReturn, priceReturn, roundOff, ...a, pending, deducted, age, creditDays, dueDate: `${dueDate.getFullYear()}-${String(dueDate.getMonth()+1).padStart(2,'0')}-${String(dueDate.getDate()).padStart(2,'0')}`, status };
}
function allInvoices() { return state.invoices.map(invoiceData); }
function totals() {
  const invoices = allInvoices();
  return {
    invoice:sum(invoices, x => x.amount), qtyReturn:sum(invoices, x => x.qtyReturn), priceReturn:sum(invoices, x => x.priceReturn),
    payment:sum(invoices, x => x.Payment), tds:sum(invoices,x=>x.TDS), ppv:sum(invoices,x=>x.PPV), pqv:sum(invoices,x=>x.PQV), ccogs:sum(invoices,x=>x.CCOGS), taxd:sum(invoices,x=>x.TaxD), pending:sum(invoices,x=>x.pending), overdue:sum(invoices.filter(x=>x.status==='overdue'),x=>x.pending), due:sum(invoices.filter(x=>x.status==='due'),x=>x.pending)
  };
}
function statusMarkup(status) { const labels={settled:'Fully settled',due:'Due',overdue:'Overdue',overadjusted:'Excess paid',matched:'Matched',review:'Difference',unmatched:'Unmatched',unallocated:'Unallocated'}; return `<span class="status ${status}">${labels[status] || status}</span>`; }
function icon(type) { return ({ invoice:'₹', payment:'↓', returns:'↩', pending:'⌛', bank:'⇄', file:'▤' }[type] || '•'); }
function navTitle(view) { return ({ dashboard:'Dashboard', invoices:'Invoice Register', customers:'Customer Summary', advice:'Payment Advice', bank:'Bank Reconciliation', returns:'Sales & Price Returns', debit:'Debit Note Register', unallocated:'Unallocated Transactions', reports:'Reports', sync:'Data Synchronisation', settings:'Settings' })[view] || view; }
function showToast(message) { const el=document.createElement('div');el.className='toast';el.textContent=message;document.getElementById('toastWrap').append(el);setTimeout(()=>el.remove(),3200); }
function esc(str='') { return String(str).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }

function kpi(label, amount, type, footer) { return `<div class="kpi"><div class="kpi-header"><span>${label}</span><span class="kpi-icon ${type === 'returns' ? 'yellow' : type === 'pending' ? 'red' : type === 'payment' ? 'teal' : ''}">${icon(type)}</span></div><div class="kpi-value">${shortMoney(amount)}</div><div class="kpi-foot">${footer}</div></div>`; }
function renderDashboard() {
  const t=totals(); const inv=allInvoices();
  const months=Array.from({length:6},(_,i)=>{
    const date=new Date(localToday.getFullYear(),localToday.getMonth()-5+i,1);
    const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;
    return {label:date.toLocaleDateString('en-IN',{month:'short'}),invoice:sum(state.invoices.filter(x=>x.date.startsWith(key)),x=>x.amount),payment:sum(state.advice.filter(x=>x.type==='Payment'&&x.date.startsWith(key)),x=>x.amount)};
  });
  const chartMax=Math.max(1,...months.flatMap(m=>[m.invoice,m.payment]));
  const buckets=[sum(inv.filter(x=>x.pending>1&&x.age>90),x=>x.pending),sum(inv.filter(x=>x.pending>1&&x.age>60&&x.age<=90),x=>x.pending),sum(inv.filter(x=>x.pending>1&&x.age>30&&x.age<=60),x=>x.pending),sum(inv.filter(x=>x.pending>1&&x.age<=30),x=>x.pending)];
  const grossPending=sum(buckets); const edges=buckets.map((_,index)=>sum(buckets.slice(0,index+1))/Math.max(1,grossPending)*100);
  const donutStyle=grossPending?`conic-gradient(#ec6b70 0 ${edges[0]}%,#f1b74a ${edges[0]}% ${edges[1]}%,#3fc1a1 ${edges[1]}% ${edges[2]}%,#5b79e5 ${edges[2]}% 100%)`:'#edf0f5';
  const customerOutstanding = customerRows().sort((a,b)=>b.pending-a.pending).slice(0,4);
  return `<section class="view">
    <div class="page-heading"><div><h1>Welcome, ${esc(sharedSession?.user.name || 'Finance team')} <span style="font-size:19px">👋</span></h1><p>Here’s the current picture of your receivables.</p></div><div class="heading-actions"><button class="btn" data-action="export" data-report="Invoice Outstanding"><span>⇩</span> Export report</button><button class="btn primary" data-action="sync"><span>↻</span> Refresh shared data</button></div></div>
    <div class="kpi-grid">
      ${kpi('Total invoice value',t.invoice,'invoice','<span>Across all invoices</span>')}
      ${kpi('Payments received',t.payment,'payment','<span>Allocated payment advice</span>')}
      ${kpi('Total returns',t.qtyReturn+t.priceReturn,'returns','<span>Qty & price adjustments</span>')}
      ${kpi('TDS & deductions',t.tds+t.ppv+t.pqv+t.ccogs+t.taxd,'returns','<span>Across payment advice</span>')}
      ${kpi('Overdue receivables',t.overdue,'pending','<span>Past customer credit terms</span>')}
      ${kpi('Due receivables',t.due,'returns','<span>Within customer credit terms</span>')}
    </div>
    <div class="dashboard-main-grid">
      <section class="panel chart-panel"><div class="panel-head"><div><h2>Invoice raised vs. payment received</h2><p>Monthly comparison of invoiced and allocated amounts</p></div><div class="panel-actions"><div class="chart-legend"><span><i class="legend-dot blue"></i>Invoice</span><span><i class="legend-dot teal"></i>Payment</span></div><span style="font-size:9px;color:#7c879b">Last 6 months</span></div></div><div class="chart-wrap"><div class="bar-chart">${months.map(m=>`<div class="bar-group"><div class="bar invoice" title="${fMoney(m.invoice)}" style="height:${m.invoice/chartMax*100}%"></div><div class="bar payment" title="${fMoney(m.payment)}" style="height:${m.payment/chartMax*100}%"></div><label>${m.label}</label></div>`).join('')}</div></div></section>
      <section class="panel chart-panel"><div class="panel-head"><div><h2>Outstanding ageing</h2><p>Pending balance by invoice age</p></div><button class="btn" data-view="invoices">View all</button></div><div class="donut-flex"><div class="donut" style="background:${donutStyle}"><div class="donut-center"><b>${shortMoney(grossPending)}</b><small>TOTAL PENDING</small></div></div><ul class="age-list"><li><span class="age-label"><i class="age-dot" style="background:#ec6b70"></i>Over 90 days</span><b>${shortMoney(buckets[0])}</b></li><li><span class="age-label"><i class="age-dot" style="background:#f1b74a"></i>61 – 90 days</span><b>${shortMoney(buckets[1])}</b></li><li><span class="age-label"><i class="age-dot" style="background:#3fc1a1"></i>31 – 60 days</span><b>${shortMoney(buckets[2])}</b></li><li><span class="age-label"><i class="age-dot" style="background:#5b79e5"></i>0 – 30 days</span><b>${shortMoney(buckets[3])}</b></li></ul></div></section>
    </div>
    <div class="lower-grid">
      <section class="panel"><div class="panel-head"><div><h2>Customer-wise outstanding</h2><p>Customers with the highest pending balance</p></div><button class="btn" data-view="customers">View summary</button></div><div class="customers-list">${customerOutstanding.map((c,i)=>`<div class="customer-row"><div class="customer-name"><span class="customer-avatar">${c.customer.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span>${esc(c.customer)}<small>${c.count} invoices · ${esc(c.code)}</small></span></div><div><small>Invoice value</small><b>${shortMoney(c.invoice)}</b></div><div><small>Overdue</small><b class="amount-red">${shortMoney(c.overdue)}</b></div><div class="align-right"><small>Due</small><b>${shortMoney(c.due)}</b></div></div>`).join('')}</div></section>
      <section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Updates from your latest data sync</p></div><button class="btn" data-view="sync">Sync history</button></div><div class="activity">${state.logs.map((log,i)=>`<div class="activity-row"><div class="activity-icon ${log.kind==='warn'?'warning':log.kind==='info'?'info':''}">${log.kind==='ok'?'✓':log.kind==='warn'?'!':'↻'}</div><p><b>${esc(log.event)}</b><br><span>${esc(log.detail)}</span></p><time>${esc(log.time)}</time></div>`).join('')}</div></section>
    </div></section>`;
}

function invoiceTable(rows) { return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Invoice date</th><th>Credit terms</th><th class="right">Invoice value</th><th class="right">Adjustments</th><th class="right">Round off</th><th class="right">Received</th><th class="right">Pending</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr class="clickable" data-invoice="${esc(x.id)}"><td><b class="strong">${esc(x.id)}</b><br><small style="color:#8d97a8">${esc(x.code)}</small></td><td>${esc(x.customer)}</td><td>${dateText(x.date)}</td><td><b>${x.creditDays} days</b><br><small style="color:#8d97a8">Due ${dateText(x.dueDate)}</small></td><td class="right">${fMoney(x.amount)}</td><td class="right">${fMoney(x.qtyReturn+x.priceReturn+x.PPV+x.PQV+x.CCOGS+x.TaxD)}</td><td class="right">${fMoney(x.roundOff)}</td><td class="right amount-green">${fMoney(x.Payment+x.TDS)}</td><td class="right ${x.pending<0?'pending-negative':x.pending>0?'pending-positive':'amount-green'}">${fMoney(x.pending)}</td><td>${statusMarkup(x.status)}</td><td><button class="btn" data-invoice="${esc(x.id)}" style="padding:5px 7px">View</button></td></tr>`).join('')}</tbody></table></div>`; }
function renderInvoices() {
  const filtered=allInvoices().filter(x => (`${esc(x.id)} ${esc(x.customer)} ${esc(x.code)}`).toLowerCase().includes(invoiceFilter.search.toLowerCase()) && (invoiceFilter.status==='all'||x.status===invoiceFilter.status)); const t=totals();
  return `<section class="view"><div class="page-heading"><div><h1>Invoice register</h1><p>Invoice-wise reconciliation with round-off control and credit-day based due status.</p></div><div class="heading-actions"><button class="btn" data-action="export" data-report="Invoice Outstanding">⇩ Export Excel</button><button class="btn primary" data-action="new-invoice">＋ Add invoice</button></div></div><section class="panel"><div class="summary-strip"><div class="summary-item"><small>Total invoices</small><b>${state.invoices.length}</b></div><div class="summary-item"><small>Invoice amount</small><b>${shortMoney(t.invoice)}</b></div><div class="summary-item"><small>Fully settled</small><b style="color:#16a77f">${allInvoices().filter(x=>x.status==='settled').length}</b></div><div class="summary-item"><small>Pending amount</small><b style="color:#d18d1b">${shortMoney(t.pending)}</b></div></div><div class="filter-bar"><div class="search-box">⌕<input id="invoiceSearch" value="${esc(invoiceFilter.search)}" placeholder="Search invoice or customer" /></div><select class="filter-select" id="statusFilter"><option value="all">All statuses</option><option value="settled" ${invoiceFilter.status==='settled'?'selected':''}>Fully settled</option><option value="due" ${invoiceFilter.status==='due'?'selected':''}>Due</option><option value="overdue" ${invoiceFilter.status==='overdue'?'selected':''}>Overdue</option></select><select class="filter-select"><option>All customers</option>${[...new Set(state.invoices.map(x=>x.customer))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="btn" data-action="clear-filters">Clear filters</button></div>${invoiceTable(filtered)}<div class="pagination"><span>Showing ${filtered.length} of ${state.invoices.length} invoices</span><div class="pages"><button>‹</button><button class="active">1</button><button>›</button></div></div></section></section>`;
}
function customerRows() { const map=Object.create(null); allInvoices().forEach(i=>{if(!map[i.customer])map[i.customer]={customer:i.customer,code:i.code,count:0,invoice:0,returns:0,payment:0,tds:0,ppv:0,pqv:0,ccogs:0,taxd:0,pending:0,overdue:0,due:0};const x=map[i.customer];x.count++;x.invoice+=i.amount;x.returns+=i.qtyReturn+i.priceReturn;x.payment+=i.Payment;x.tds+=i.TDS;x.ppv+=i.PPV;x.pqv+=i.PQV;x.ccogs+=i.CCOGS;x.taxd+=i.TaxD;x.pending+=i.pending;if(i.status==='overdue')x.overdue+=i.pending;if(i.status==='due')x.due+=i.pending;});return Object.values(map); }
function renderCustomers() { const rows=customerRows().sort((a,b)=>b.pending-a.pending);return `<section class="view"><div class="page-heading"><div><h1>Customer summary</h1><p>Overdue and due balances based on each customer’s credit terms.</p></div><div class="heading-actions"><button class="btn primary" data-action="customer-terms">Manage credit days</button><button class="btn" data-action="export" data-report="Customer Outstanding">⇩ Export Excel</button></div></div><div class="customer-cards">${rows.slice(0,3).map(c=>`<section class="panel customer-card" data-customer="${esc(c.customer)}"><div class="customer-card-head"><span class="customer-avatar">${c.customer.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div><h3>${esc(c.customer)}</h3><p>${esc(c.code)} · ${c.count} invoices</p></div></div><div class="balance-split"><div><small>Overdue</small><b class="amount-red">${shortMoney(c.overdue)}</b></div><div><small>Due</small><b>${shortMoney(c.due)}</b></div></div><span class="status ${c.pending?'partial':'settled'}">${c.pending?'Outstanding balance':'Fully settled'}</span><div class="meter"><span style="width:${Math.min(100,((c.invoice-c.pending)/c.invoice)*100)}%"></span></div><div class="customer-card-foot"><span>Collection rate</span><b>${((c.invoice-c.pending)/c.invoice*100).toFixed(1)}%</b></div></section>`).join('')}</div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>All customers</h2><p>Click a customer to drill into their invoice ledger.</p></div><div class="search-box">⌕<input placeholder="Search customer" /></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th class="right">Invoice amount</th><th class="right">Returns</th><th class="right">Payment</th><th class="right">TDS</th><th class="right">Other deductions</th><th>Credit days</th><th class="right">Overdue</th><th class="right">Due</th><th class="right">Pending amount</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr class="clickable" data-customer="${esc(c.customer)}"><td><b class="strong">${esc(c.customer)}</b><br><small style="color:#8c96a7">${esc(c.code)} · ${c.count} invoices</small></td><td class="right">${fMoney(c.invoice)}</td><td class="right">${fMoney(c.returns)}</td><td class="right amount-green">${fMoney(c.payment)}</td><td class="right">${fMoney(c.tds)}</td><td class="right">${fMoney(c.ppv+c.pqv+c.ccogs+c.taxd)}</td><td>${customerCreditDays(c.customer)} days</td><td class="right amount-red">${fMoney(c.overdue)}</td><td class="right">${fMoney(c.due)}</td><td class="right ${c.pending?'pending-positive':'amount-green'}">${fMoney(c.pending)}</td><td>›</td></tr>`).join('')}</tbody></table></div></section></section>`; }

function renderAdvice() { const rows=state.advice;const unallocated=rows.filter(x=>!x.invoice);return `<section class="view"><div class="page-heading"><div><h1>Payment advice</h1><p>Invoice-level allocation instructions submitted by customers. Bank reference / UTR is mandatory and selected from unmapped bank receipts.</p></div><div class="heading-actions"><button class="btn" data-action="export" data-report="Payment Advice">⇩ Export Excel</button><button class="btn primary" data-action="add-advice">＋ Add advice</button></div></div><section class="panel"><div class="summary-strip"><div class="summary-item"><small>Total advice entries</small><b>${rows.length}</b></div><div class="summary-item"><small>Allocated entries</small><b style="color:#16a77f">${rows.length-unallocated.length}</b></div><div class="summary-item"><small>Unallocated entries</small><b style="color:#4870df">${unallocated.length}</b></div><div class="summary-item"><small>Classification rules</small><b>6 permitted types</b></div></div><div class="filter-bar"><div class="search-box">⌕<input placeholder="Search advice, invoice or UTR" /></div><select class="filter-select"><option>All transaction types</option><option>Payment</option><option>TDS</option><option>PPV</option><option>PQV</option><option>CCOGS</option><option>TaxD</option></select><button class="btn" data-view="unallocated">View unallocated</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Advice number</th><th>Date</th><th>Customer</th><th>Invoice</th><th>Transaction type</th><th>Transaction description</th><th>Bank reference / UTR</th><th class="right">Amount</th><th>Allocation</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="strong">${esc(x.id)}</td><td>${dateText(x.date)}</td><td>${esc(x.customer)}</td><td>${x.invoice?`<button data-invoice="${esc(x.invoice)}" style="color:#4268dc;font-weight:800">${esc(x.invoice)}</button>`:'<span style="color:#5576dc;font-weight:800">Unallocated</span>'}</td><td><span class="status ${x.type==='Payment'?'matched':x.type==='TDS'?'review':'unallocated'}">${esc(x.type)}</span></td><td>${esc(x.description||'—')}</td><td style="font-family:DM Mono">${x.utr||'—'}</td><td class="right strong">${fMoney(x.amount)}</td><td>${statusMarkup(x.invoice?'matched':'unallocated')}</td></tr>`).join('')}</tbody></table></div></section></section>`; }
function renderBank() { const bank=state.bank; const matched=bank.filter(x=>x.status==='matched'), unmatched=bank.filter(x=>x.status==='unmatched'), review=bank.filter(x=>x.status==='review'); const bankTotal=sum(bank,x=>x.amount), adviceTotal=sum(state.advice.filter(x=>x.type==='Payment'),x=>x.amount);return `<section class="view"><div class="page-heading"><div><h1>Bank reconciliation</h1><p>Compare cleared bank credits with payment advice allocations. Payment advice alone is not proof of receipt.</p></div><div class="heading-actions"><button class="btn" data-action="export" data-report="Bank Reconciliation">⇩ Export report</button><button class="btn" data-action="new-bank">＋ Add bank receipt</button><button class="btn primary" data-action="match-selected">⇄ Match transactions</button></div></div><div class="recon-cards"><div class="panel mini-kpi"><small>Bank credits</small><b>${shortMoney(bankTotal)}</b><span>${bank.length} receipt transactions</span></div><div class="panel mini-kpi"><small>Advice payments</small><b>${shortMoney(adviceTotal)}</b><span>${state.advice.filter(x=>x.type==='Payment').length} allocation records</span></div><div class="panel mini-kpi"><small>Matched payments</small><b style="color:#18a37d">${matched.length}</b><span>${shortMoney(sum(matched,x=>x.amount))} verified</span></div><div class="panel mini-kpi"><small>Needs attention</small><b style="color:#d6535c">${unmatched.length+review.length}</b><span>${unmatched.length} unmatched · ${review.length} difference</span></div></div><div class="bank-split"><section class="panel"><div class="panel-head"><div><h2>Receipt matching queue</h2><p>Review exceptions before confirming reconciliation.</p></div><button class="btn" data-action="match-selected">Match all eligible</button></div>${bank.filter(x=>x.status!=='matched').map(x=>`<div class="recon-item"><div class="recon-check ${x.status==='unmatched'?'bad':'warn'}">${x.status==='unmatched'?'!':'±'}</div><div><b>${esc(x.ref)}</b><small>${dateText(x.date)} · ${x.customer||'Customer not identified'}${x.advice?` · ${esc(x.advice)}`:''}</small></div><div class="amt"><b>${fMoney(x.amount)}</b><div>${statusMarkup(x.status)}</div></div><button class="btn" data-action="map-bank" data-ref="${esc(x.ref)}" style="padding:6px 8px">Map</button></div>`).join('') || '<div class="empty-state"><div class="empty-icon">✓</div><h3>Everything is reconciled</h3><p>There are no bank transactions that require review.</p></div>'}</section><section class="panel"><div class="panel-head"><div><h2>Reconciliation controls</h2><p>Matching policy</p></div></div><div class="detail-section" style="border:0;border-radius:0"><div class="allocation-row"><span>Match using UTR / bank reference</span><b style="color:#1aa27d">Enabled</b></div><div class="allocation-row"><span>Auto-match exact amount</span><b style="color:#1aa27d">Enabled</b></div><div class="allocation-row"><span>Flag duplicate bank reference</span><b style="color:#d8555e">${bank.filter((x,i,a)=>a.findIndex(y=>y.ref===x.ref)!==i).length||0} found</b></div><div class="allocation-row"><span>Allowed difference</span><b>₹0</b></div></div><div style="padding:0 17px 17px"><div style="background:#fff5df;border-radius:7px;padding:12px;font-size:10px;color:#946e20;line-height:1.6">Payments are posted to invoice balances only from validated Payment Advice entries. Bank receipts remain separately verified here.</div></div></section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>All bank receipts</h2><p>Imported credit transactions from the latest statement.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Transaction date</th><th>Bank reference / UTR</th><th>Customer</th><th>Advice reference</th><th class="right">Credit amount</th><th>Status</th><th></th></tr></thead><tbody>${bank.map(x=>`<tr><td>${dateText(x.date)}</td><td class="strong" style="font-family:DM Mono">${esc(x.ref)}</td><td>${x.customer||'—'}</td><td>${x.advice||'—'}</td><td class="right strong">${fMoney(x.amount)}</td><td>${statusMarkup(x.status)}</td><td>${x.status!=='matched'?`<button class="btn" data-action="map-bank" data-ref="${esc(x.ref)}" style="padding:5px 8px">Map</button>`:'✓'}</td></tr>`).join('')}</tbody></table></div></section></section>`; }
function renderReturns() { const rows=[...state.returns.map(x=>({...x,kind:'Qty return'})),...state.priceReturns.map(x=>({...x,kind:'Price return',qty:'—',product:x.reason}))].sort((a,b)=>b.date.localeCompare(a.date)); return `<section class="view"><div class="page-heading"><div><h1>Sales & price returns</h1><p>Returns and credit adjustments mapped to original invoice records.</p></div><div class="heading-actions"><button class="btn" data-action="export" data-report="Returns">⇩ Export report</button><button class="btn primary" data-action="import">⇧ Import return file</button></div></div><section class="panel"><div class="summary-strip"><div class="summary-item"><small>Quantity returns</small><b>${fMoney(sum(state.returns,x=>x.amount))}</b></div><div class="summary-item"><small>Price returns</small><b>${fMoney(sum(state.priceReturns,x=>x.amount))}</b></div><div class="summary-item"><small>Mapped to invoices</small><b style="color:#1ca37d">${rows.length}</b></div><div class="summary-item"><small>Unmapped returns</small><b>0</b></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Document no.</th><th>Type</th><th>Date</th><th>Customer</th><th>Original invoice</th><th>Product / reason</th><th class="right">Return qty</th><th class="right">Amount</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="strong">${esc(x.id)}</td><td><span class="status ${x.kind==='Qty return'?'review':'unallocated'}">${x.kind}</span></td><td>${dateText(x.date)}</td><td>${esc(x.customer)}</td><td><button data-invoice="${esc(x.invoice)}" style="color:#4168dc;font-weight:800">${esc(x.invoice)}</button></td><td>${esc(x.product)}</td><td class="right">${x.qty}</td><td class="right strong">${fMoney(x.amount)}</td></tr>`).join('')}</tbody></table></div></section></section>`; }
function renderDebit() { return `<section class="view"><div class="page-heading"><div><h1>Debit note register</h1><p>Buyer-raised debit notes, reviewed separately to prevent double counting.</p></div><div class="heading-actions"><button class="btn" data-action="export" data-report="Debit Note Register">⇩ Export report</button><button class="btn primary" data-action="new-debit">＋ Add debit note</button></div></div><section class="panel"><div class="summary-strip"><div class="summary-item"><small>Total debit notes</small><b>${state.debitNotes.length}</b></div><div class="summary-item"><small>Debit note value</small><b>${shortMoney(sum(state.debitNotes,x=>x.amount))}</b></div><div class="summary-item"><small>Already included</small><b style="color:#19a47d">${state.debitNotes.filter(x=>x.status!=='Unmapped').length}</b></div><div class="summary-item"><small>Requires allocation</small><b style="color:#4d6fdb">${state.debitNotes.filter(x=>x.status==='Unmapped').length}</b></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Debit note number</th><th>Date</th><th>Customer</th><th>Original invoice</th><th>Debit note type</th><th class="right">Amount</th><th>Mapping status</th><th></th></tr></thead><tbody>${state.debitNotes.map(x=>`<tr><td class="strong">${esc(x.id)}</td><td>${dateText(x.date)}</td><td>${esc(x.customer)}</td><td>${x.invoice?`<button data-invoice="${esc(x.invoice)}" style="color:#4168dc;font-weight:800">${esc(x.invoice)}</button>`:'—'}</td><td><span class="status ${x.type==='Unknown'?'unallocated':'review'}">${x.type||'Unknown'}</span></td><td class="right strong">${fMoney(x.amount)}</td><td>${x.status==='Unmapped'?statusMarkup('unallocated'):`<span class="status matched">${esc(x.status)}</span>`}</td><td>${x.status==='Unmapped'?`<button class="btn" data-action="map-debit" data-ref="${esc(x.id)}" style="padding:5px 8px">Map</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section></section>`; }
function renderUnallocated() { const advice=state.advice.filter(x=>!x.invoice);const bank=state.bank.filter(x=>x.status==='unmatched'); return `<section class="view"><div class="page-heading"><div><h1>Unallocated transactions</h1><p>Transactions that need an invoice or customer mapping before they can be reconciled.</p></div><div class="heading-actions"><button class="btn" data-action="export" data-report="Unallocated Transactions">⇩ Export report</button></div></div><div class="recon-cards"><div class="panel mini-kpi"><small>Unallocated advice</small><b>${advice.length}</b><span>${shortMoney(sum(advice,x=>x.amount))} to allocate</span></div><div class="panel mini-kpi"><small>Unmatched bank receipts</small><b>${bank.length}</b><span>${shortMoney(sum(bank,x=>x.amount))} to review</span></div><div class="panel mini-kpi"><small>Import exceptions</small><b>0</b><span>All source schemas valid</span></div><div class="panel mini-kpi"><small>Open work items</small><b style="color:#d6535c">${advice.length+bank.length}</b><span>Awaiting finance review</span></div></div><section class="panel"><div class="panel-head"><div><h2>Allocation queue</h2><p>Assign a customer and original invoice, or retain an item as an exception.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Date</th><th>Reference</th><th>Customer</th><th>Transaction type</th><th class="right">Amount</th><th>Issue</th><th></th></tr></thead><tbody>${[...advice.map(x=>({source:'Payment Advice',date:x.date,ref:x.id,customer:x.customer,type:x.type,amount:x.amount,issue:'Missing invoice reference',action:'map-advice'})),...bank.map(x=>({source:'Bank Statement',date:x.date,ref:x.ref,customer:'—',type:'Bank credit',amount:x.amount,issue:'No matched payment advice',action:'map-bank'}))].map(x=>`<tr><td>${x.source}</td><td>${dateText(x.date)}</td><td class="strong">${esc(x.ref)}</td><td>${esc(x.customer)}</td><td>${esc(x.type)}</td><td class="right strong">${fMoney(x.amount)}</td><td>${statusMarkup('unallocated')} <small style="color:#8791a2">${x.issue}</small></td><td><button class="btn primary" data-action="${x.action}" data-ref="${esc(x.ref)}" style="padding:6px 8px">Allocate</button></td></tr>`).join('')}</tbody></table></div></section></section>`; }
function renderReports() { const reports=[['Invoice-wise Outstanding Report','Invoice balance, adjustment and ageing status by invoice.','Invoice Outstanding'],['Customer-wise Outstanding Report','Consolidated receivables and collection position by customer.','Customer Outstanding'],['Bank Reconciliation Report','Cleared bank receipts compared to payment advice.','Bank Reconciliation'],['Debit Note Register','Buyer debit notes and double-count protection review.','Debit Note Register'],['Unallocated Transaction Report','Payment advice and bank credits without an invoice mapping.','Unallocated Transactions'],['Fully Settled Invoice Report','Invoices with zero balance after reconciled adjustments.','Settled Invoices'],['Ageing Report','Outstanding balance bucketed by number of days open.','Ageing']];return `<section class="view"><div class="page-heading"><div><h1>Reports</h1><p>Export operational reconciliation reports to Excel-compatible CSV files.</p></div></div><section class="panel"><div class="panel-head"><div><h2>Available reports</h2><p>All exports use the live reconciliation data in this workspace.</p></div></div><div class="report-list">${reports.map(([name,desc,kind])=>`<div class="report-row"><div class="report-icon">▤</div><div><b>${name}</b><p>${desc}</p></div><button class="btn" data-action="export" data-report="${kind}">⇩ Export Excel</button></div>`).join('')}</div></section></section>`; }
function renderSync() {return `<section class="view"><div class="page-heading"><div><h1>Shared data</h1><p>Changes are saved centrally and checked for updates every 30 seconds.</p></div><button class="btn primary" data-action="sync">Refresh shared data</button></div><section class="panel"><div class="panel-head"><div><h2>Workspace status</h2><p>Revision ${workspaceRevision} · ${state.invoices.length} invoices · ${state.bank.length} bank receipts</p></div><span class="status matched">Shared database</span></div></section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>OneDrive and source-file imports</h2><p>Not configured. Add records manually or ask an administrator to import a workspace JSON backup.</p></div></div></section></section>`;}

function renderSettings() { return `<section class="view"><div class="page-heading"><div><h1>Settings</h1><p>Shared workspace access, data recovery and integrations.</p></div></div>
<section class="panel"><div class="panel-head"><div><h2>Your account</h2><p>${esc(sharedSession?.user.email || '')} · ${esc(sharedSession?.user.role || 'test')}</p></div><button class="btn" data-team-action="password">Change password</button></div></section>
${sharedSession?.user.role === 'admin' ? `<section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>Team access</h2><p>Create accounts, assign roles, reset passwords or disable access.</p></div><button class="btn primary" data-team-action="users">Manage users</button></div></section>
<section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>Backups & history</h2><p>Download a workspace backup, review changes or restore a previous revision.</p></div></div><div class="team-actions"><button class="btn" data-team-action="backup">Download backup</button><button class="btn" data-team-action="restore">Import / restore JSON</button><button class="btn" data-team-action="legacy">Import existing browser data</button><button class="btn" data-team-action="snapshots">Previous revisions</button><button class="btn" data-team-action="audit">Activity history</button></div></section>` : ''}
<section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>Microsoft OneDrive</h2><p>Not connected. OAuth and Excel imports require a separate integration.</p></div><span class="status unallocated">Not configured</span></div></section></section>`; }


function render() { document.getElementById('bankBadge').textContent=state.bank.filter(row=>row.status!=='matched').length;document.getElementById('unallocatedBadge').textContent=state.advice.filter(row=>!row.invoice).length+state.bank.filter(row=>row.status==='unmatched').length;document.getElementById('breadcrumb').innerHTML=`<span>Workspace</span><b>/</b><strong>${navTitle(currentView)}</strong>`;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===currentView)); const renderers={dashboard:renderDashboard,invoices:renderInvoices,customers:renderCustomers,advice:renderAdvice,bank:renderBank,returns:renderReturns,debit:renderDebit,unallocated:renderUnallocated,reports:renderReports,sync:renderSync,settings:renderSettings}; app.innerHTML=renderers[currentView](); bindPageEvents(); }
function bindPageEvents() {
  app.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));
  app.querySelectorAll('[data-invoice]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openInvoice(b.dataset.invoice)}));
  app.querySelectorAll('[data-customer]').forEach(b=>b.addEventListener('click',()=>openCustomer(b.dataset.customer)));
  app.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();Promise.resolve(action(b.dataset.action,b.dataset)).catch(error=>showToast(error.message))}));
  if (sharedSession?.user.role === 'viewer') app.querySelectorAll('[data-action]').forEach(button=>{if(!['export','clear-filters','sync'].includes(button.dataset.action)){button.disabled=true;button.title='Viewer access';}});
  window.bindTeamControls?.();
  const search=document.getElementById('invoiceSearch');if(search)search.addEventListener('input',e=>{invoiceFilter.search=e.target.value;render();});
  const status=document.getElementById('statusFilter');if(status)status.addEventListener('change',e=>{invoiceFilter.status=e.target.value;render();});
}
function go(view) { currentView=view;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo(0,0); }

function action(name,data) { if(name==='export') return exportReport(data.report); if(name==='sync') return runSync(); if(name==='import') return openImport();if(name==='connect-onedrive') return openConnect();if(name==='new-invoice')return openNewInvoice();if(name==='new-bank')return openBankReceipt();if(name==='customer-terms')return openCustomerTerms();if(name==='add-advice')return openAdvice();if(name==='new-debit')return openDebit();if(name==='map-bank'||name==='map-advice'||name==='map-debit')return openMap(name,data.ref);if(name==='match-selected')return matchEligible();if(name==='clear-filters'){invoiceFilter={search:'',status:'all'};return render();}if(name==='reset-data'){if(sharedSession)return showToast('Shared data can only be replaced through an administrator backup restore.');state=clone(seed);initializeCustomerTerms();persist();render();return showToast('Sample workspace restored.');}if(name==='view-errors')return showToast('Source-file import is not configured.'); }
function modal(title,subtitle,content,footer='') { const layer=document.getElementById('modalLayer');layer.innerHTML=`<div class="modal"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle||'')}</p></div><button class="modal-close" data-close-modal>×</button></div><div class="modal-content">${content}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div>`;layer.classList.remove('hidden');layer.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModal);layer.onclick=e=>{if(e.target===layer)closeModal();};return layer; }
function closeModal(){document.getElementById('modalLayer').classList.add('hidden');}
function openInvoice(id) { const x=allInvoices().find(i=>i.id===id);if(!x)return;const ret=state.returns.filter(r=>r.invoice===id),pr=state.priceReturns.filter(r=>r.invoice===id),adv=state.advice.filter(a=>a.invoice===id),bank=state.bank.filter(b=>adv.some(a=>a.utr===b.ref));const deducted=[['Qty return',x.qtyReturn],['Price return',x.priceReturn],['Payment',x.Payment],['TDS',x.TDS],['PPV',x.PPV],['PQV',x.PQV],['CCOGS',x.CCOGS],['TaxD',x.TaxD],['Round off',x.roundOff]];modal(`Invoice ${x.id}`,`${x.customer} · ${x.code}`,`<div class="detail-top"><div><small>Invoice date</small><b>${dateText(x.date)}</b></div><div><small>Invoice value</small><b>${fMoney(x.amount)}</b></div><div><small>Total adjusted</small><b>${fMoney(x.deducted+x.roundOff)}</b></div><div><small>Pending amount</small><b class="detail-highlight">${fMoney(x.pending)}</b></div></div><div class="detail-grid"><section class="detail-section"><h3>Reconciliation allocation</h3>${deducted.map(([n,v])=>`<div class="allocation-row"><span>${n}</span><b class="amount">${fMoney(v)}</b></div>`).join('')}<div class="allocation-row" style="margin-top:4px"><b>Final pending</b><b class="amount ${x.pending?'detail-highlight':''}">${fMoney(x.pending)}</b></div></section><section class="detail-section"><h3>Original invoice</h3><div class="allocation-row"><span>Quantity</span><b>${x.qty}</b></div><div class="allocation-row"><span>Rate</span><b>${fMoney(x.rate)}</b></div><div class="allocation-row"><span>Credit terms</span><b>${x.creditDays} days</b></div><div class="allocation-row"><span>Due date</span><b>${dateText(x.dueDate)}</b></div><div class="allocation-row"><span>Age</span><b>${x.age} days</b></div><div class="allocation-row"><span>Reconciliation status</span>${statusMarkup(x.status)}</div></section></div><section class="detail-section" style="margin-top:15px"><h3>Transaction history</h3><table class="data-table" style="min-width:0"><thead><tr><th>Date</th><th>Reference</th><th>Transaction</th><th class="right">Amount</th></tr></thead><tbody>${[...ret.map(r=>({date:r.date,ref:r.id,type:'Quantity return',amount:r.amount})),...pr.map(r=>({date:r.date,ref:r.id,type:'Price return',amount:r.amount})),...adv.map(a=>({date:a.date,ref:a.id+' · '+a.utr,type:a.type,amount:a.amount})),...bank.map(b=>({date:b.date,ref:b.ref,type:'Verified bank receipt',amount:b.amount}))].sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<tr><td>${dateText(r.date)}</td><td>${esc(r.ref)}</td><td>${esc(r.type)}</td><td class="right strong">${fMoney(r.amount)}</td></tr>`).join('')||'<tr><td colspan="4" style="text-align:center;color:#8d97a8">No adjustments recorded</td></tr>'}</tbody></table></section>`,`<button class="btn" data-close-modal>Close</button><button class="btn" id="editRoundOff">Edit round off</button><button class="btn primary" data-modal-export="${esc(x.id)}">⇩ Export reconciliation</button>`);document.getElementById('editRoundOff').disabled=sharedSession?.user.role==='viewer';document.getElementById('editRoundOff').onclick=()=>openRoundOff(id);document.querySelector('[data-modal-export]')?.addEventListener('click',()=>exportReport('Invoice Outstanding',[x])); }
function openCustomer(customer) { const rows=allInvoices().filter(x=>x.customer===customer);const c=customerRows().find(x=>x.customer===customer);modal(customer,`${c.code} · ${c.count} invoice${c.count>1?'s':''}`,`<div class="detail-top"><div><small>Invoice value</small><b>${fMoney(c.invoice)}</b></div><div><small>Returns</small><b>${fMoney(c.returns)}</b></div><div><small>Payment received</small><b>${fMoney(c.payment)}</b></div><div><small>Pending amount</small><b class="detail-highlight">${fMoney(c.pending)}</b></div></div><div class="balance-split"><div><small>Overdue</small><b class="amount-red">${fMoney(c.overdue)}</b></div><div><small>Due</small><b>${fMoney(c.due)}</b></div></div><div style="margin-top:16px">${invoiceTable(rows)}</div>`,`<button class="btn" data-close-modal>Close</button><button class="btn primary" data-modal-export="customer">⇩ Export customer ledger</button>`);document.querySelector('[data-modal-export]')?.addEventListener('click',()=>exportReport('Customer Outstanding',rows)); }
function openImport() {modal('Source-file import', 'Excel and CSV ingestion is not configured.', '<p>Use Add invoice or Add advice for individual records. Administrators can import an existing workspace JSON file under Settings → Backups & history.</p>', '<button class="btn" data-close-modal>Close</button>');}

function openConnect(){modal('Microsoft OneDrive','Not configured.','<p>Microsoft OAuth credentials, source-file parsing and scheduled imports must be configured before OneDrive sync is available.</p>','<button class="btn" data-close-modal>Close</button>');}

function openCustomerTerms() {
  modal('Customer credit days', 'Changes apply to every existing and future invoice for the customer.',
    `<div class="mapping-grid">${state.customerTerms.map((term,index)=>`<label>${esc(term.customer)}<input data-term-index="${index}" data-term-customer="${esc(term.customer)}" type="number" min="0" step="1" value="${term.creditDays}" /></label>`).join('')}</div>`,
    `<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveCustomerTerms">Save credit days</button>`);
  document.getElementById('saveCustomerTerms').onclick=async ()=>{try{
    const inputs=[...document.querySelectorAll('[data-term-index]')];
    if(inputs.some(input=>input.value.trim()===''||!Number.isInteger(Number(input.value))||Number(input.value)<0||Number(input.value)>3650)){
      showToast('Enter whole credit days from 0 to 3650 for each customer.');return;
    }
    inputs.forEach(input=>{const term=state.customerTerms.find(t=>customerKey(t.customer)===customerKey(input.dataset.termCustomer || state.customerTerms[Number(input.dataset.termIndex)].customer));if(term)term.creditDays=Number(input.value);});
    await persist();closeModal();render();showToast('Customer credit days saved. All invoice due dates recalculated.');
  }catch(error){showToast(error.message);}};
}

function openNewInvoice(){modal('Add invoice','Create a sales invoice record. Credit days are applied automatically from the customer mapping (45 days for a new customer).',`<div class="mapping-grid"><label>Invoice number<input id="newInvId" placeholder="INV-2026-00XXX" /></label><label>Customer name<input id="newInvCustomer" list="invoiceCustomers" placeholder="Customer name" /><datalist id="invoiceCustomers">${state.customerTerms.map(t=>`<option value="${esc(t.customer)}"></option>`).join('')}</datalist></label><label>Customer code<input id="newInvCode" placeholder="CUS-001" /></label><label>Invoice date<input id="newInvDate" type="date" value="${today}" /></label><label>Invoice amount<input id="newInvAmount" type="number" placeholder="0" /></label><label>Round off<input id="newInvRoundOff" type="number" step="0.01" value="0" /></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveInvoice">Save invoice</button>`);document.getElementById('saveInvoice').onclick=async ()=>{try{const id=document.getElementById('newInvId').value.trim(),customer=document.getElementById('newInvCustomer').value.trim(),amount=+document.getElementById('newInvAmount').value,roundOff=+document.getElementById('newInvRoundOff').value;if(!id||!customer||!amount){showToast('Invoice number, customer and amount are required.');return;}if(state.invoices.some(x=>x.id===id)){showToast('That invoice number already exists.');return;}state.invoices.unshift({id,customer,code:document.getElementById('newInvCode').value||'—',date:document.getElementById('newInvDate').value,amount,roundOff,qty:0,rate:0});initializeCustomerTerms();await persist();closeModal();render();showToast('Invoice saved and added to reconciliation.');}catch(error){showToast(error.message);}}; }
function openRoundOff(id){const invoice=state.invoices.find(x=>x.id===id);if(!invoice)return;const calculated=invoiceData(invoice);modal(`Round off · ${id}`,'Set a signed adjustment to clear a small balance. Positive values reduce pending. Credit days are managed by customer in Customer Summary.',`<div class="detail-top"><div><small>Current pending</small><b>${fMoney(calculated.pending)}</b></div><div><small>Current round off</small><b>${fMoney(calculated.roundOff)}</b></div><div><small>Credit days</small><b>${calculated.creditDays} days</b></div><div><small>Due date</small><b>${dateText(calculated.dueDate)}</b></div></div><div class="mapping-grid" style="margin-top:16px"><label>Round off amount<input id="roundOffAmount" type="number" step="0.01" value="${calculated.roundOff}" /></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveRoundOff">Save round off</button>`);document.getElementById('saveRoundOff').onclick=async ()=>{try{const roundOff=Number(document.getElementById('roundOffAmount').value);if(!Number.isFinite(roundOff)){showToast('Enter a valid round-off value.');return;}const target=state.invoices.find(x=>x.id===id);if(!target)throw new Error('This invoice no longer exists. Close this form and refresh.');target.roundOff=roundOff;await persist();closeModal();render();showToast('Round off saved; pending status recalculated.');}catch(error){showToast(error.message);}};}
function openAdvice(){const opts=state.invoices.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} — ${esc(x.customer)}</option>`).join('');const bankRefs=state.bank.filter((x,i,a)=>x.status==='unmatched'&&a.findIndex(y=>y.ref===x.ref)===i);const utrOptions=bankRefs.map(x=>`<option value="${esc(x.ref)}">${esc(x.ref)} · ${dateText(x.date)} · ${fMoney(x.amount)}</option>`).join('');modal('Add payment advice entry','Select a mandatory bank reference from the unmapped bank receipts; transaction classification is restricted to six approved values.',`<div class="mapping-grid"><label>Customer<input id="advCustomer" placeholder="Customer name" /></label><label>Advice number<input id="advId" placeholder="PA-260XXX" /></label><label>Advice date<input id="advDate" type="date" value="${today}" /></label><label>Invoice <select id="advInvoice"><option value="">— Unallocated —</option>${opts}</select></label><label>Transaction type<select id="advType"><option>Payment</option><option>TDS</option><option>PPV</option><option>PQV</option><option>CCOGS</option><option>TaxD</option></select></label><label>Amount<input id="advAmount" type="number" placeholder="0" /></label><label>Transaction description<input id="advDescription" placeholder="Enter any description" /></label><label>Bank reference / UTR *<select id="advUtr"><option value="">Select an unmapped bank receipt</option>${utrOptions}</select></label></div>${bankRefs.length?'':'<div style="margin-top:12px;background:#fff5df;border-radius:7px;padding:10px;font-size:10px;color:#8d6d24">No unmapped bank receipts are available. Import or map a bank statement receipt first.</div>'}`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveAdvice">Save allocation</button>`);document.getElementById('advInvoice').onchange=e=>{if(e.target.value){const x=state.invoices.find(a=>a.id===e.target.value);document.getElementById('advCustomer').value=x.customer;}};document.getElementById('saveAdvice').onclick=async ()=>{try{const amount=+document.getElementById('advAmount').value,id=document.getElementById('advId').value.trim(),customer=document.getElementById('advCustomer').value.trim(),utr=document.getElementById('advUtr').value;if(!amount||!id||!customer||!utr){showToast('Advice number, customer, amount and bank reference / UTR are required.');return;}if(!bankRefs.some(x=>x.ref===utr)){showToast('Select a bank reference from the unmapped bank receipts.');return;}state.advice.unshift({id,customer,date:document.getElementById('advDate').value,invoice:document.getElementById('advInvoice').value,type:document.getElementById('advType').value,description:document.getElementById('advDescription').value.trim(),amount,utr});await persist();closeModal();render();showToast('Payment advice allocation saved.');}catch(error){showToast(error.message);}}; }
function openDebit(){modal('Add debit note','Debit notes are retained for audit and are not deducted automatically.',`<div class="mapping-grid"><label>Debit note number<input id="dnId" placeholder="DN-XXXX" /></label><label>Customer name<input id="dnCustomer" placeholder="Customer name" /></label><label>Date<input id="dnDate" type="date" value="${today}" /></label><label>Original invoice<select id="dnInvoice"><option value="">— No invoice reference —</option>${state.invoices.map(x=>`<option value="${esc(x.id)}">${esc(x.id)}</option>`).join('')}</select></label><label>Amount<input id="dnAmount" type="number" placeholder="0" /></label><label>Debit note type<select id="dnType"><option>PPV</option><option>PQV</option><option>CCOGS</option><option>TAXD</option><option selected>Unknown</option></select></label></div><p style="font-size:9px;color:#8a95a8">The record will be marked Unmapped until its treatment is represented in payment advice or approved for adjustment.</p>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveDebit">Save debit note</button>`);document.getElementById('saveDebit').onclick=async ()=>{try{const id=document.getElementById('dnId').value.trim(),customer=document.getElementById('dnCustomer').value.trim(),amount=+document.getElementById('dnAmount').value;if(!id||!customer||!amount){showToast('Debit note number, customer and amount are required.');return;}state.debitNotes.unshift({id,customer,date:document.getElementById('dnDate').value,invoice:document.getElementById('dnInvoice').value,amount,type:document.getElementById('dnType').value,status:'Unmapped'});await persist();closeModal();render();showToast('Debit note added for review.');}catch(error){showToast(error.message);}}; }
function openMap(kind,ref){ const candidate=kind==='map-bank'?state.bank.find(x=>x.ref===ref):kind==='map-advice'?state.advice.find(x=>x.id===ref):state.debitNotes.find(x=>x.id===ref);if(!candidate)return;const source=kind==='map-bank'?'bank receipt':kind==='map-advice'?'payment advice':'debit note';modal(`Map ${source}`,'Choose the customer and invoice to resolve this transaction.',`<div class="detail-top"><div><small>Reference</small><b>${esc(candidate.ref||candidate.id)}</b></div><div><small>Date</small><b>${dateText(candidate.date)}</b></div><div><small>Amount</small><b>${fMoney(candidate.amount)}</b></div><div><small>Current customer</small><b>${esc(candidate.customer||'Unknown')}</b></div></div><div class="mapping-grid" style="margin-top:16px"><label>Customer<select id="mapCustomer"><option value="">Select customer</option>${[...new Set(state.invoices.map(x=>x.customer))].map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><label>Invoice<select id="mapInvoice"><option value="">Select invoice</option>${state.invoices.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} — ${esc(x.customer)}</option>`).join('')}</select></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveMap">Confirm mapping</button>`);document.getElementById('mapInvoice').onchange=e=>{if(e.target.value){const i=state.invoices.find(x=>x.id===e.target.value);document.getElementById('mapCustomer').value=i.customer;}};document.getElementById('saveMap').onclick=async ()=>{try{const invoice=document.getElementById('mapInvoice').value,customer=document.getElementById('mapCustomer').value;if(!invoice||!customer){showToast('Select both customer and invoice to complete mapping.');return;}const target=kind==='map-bank'?state.bank.find(x=>x.ref===ref):kind==='map-advice'?state.advice.find(x=>x.id===ref):state.debitNotes.find(x=>x.id===ref);if(!target)throw new Error('This transaction no longer exists. Refresh and try again.');if(kind==='map-bank'){target.customer=customer;target.status='review';target.advice='Manual mapping';}else if(kind==='map-advice'){target.invoice=invoice;target.customer=customer;}else{target.invoice=invoice;target.customer=customer;target.status='Included in adjustment';}await persist();closeModal();render();showToast(`${source[0].toUpperCase()+source.slice(1)} mapped successfully.`);}catch(error){showToast(error.message);}}; }
async function matchEligible(){try{
  let changed=0;
  state.bank.filter(row=>row.status!=='matched').forEach(receipt=>{
    if(state.bank.filter(row=>row.ref===receipt.ref).length!==1)return;
    const payments=state.advice.filter(advice=>advice.utr===receipt.ref&&advice.type==='Payment');
    if(payments.length&&Math.abs(sum(payments,row=>row.amount)-receipt.amount)<0.005){
      receipt.status='matched';receipt.advice=[...new Set(payments.map(row=>row.id))].join(', ');
      receipt.customer=[...new Set(payments.map(row=>row.customer))].join(', ');changed++;
    }
  });
  if(changed){await persist();render();}
  showToast(changed?`${changed} receipts matched successfully.`:'No exact amount/UTR matches were eligible. Duplicate references require review.');
}catch(error){showToast(error.message);}}

async function runSync(){try{await window.refreshWorkspace();showToast('Shared workspace refreshed. OneDrive sync is not connected.');}catch(error){showToast(error.message);}}

function csvEscape(v){const raw=String(v??'');const s=typeof v==='string'&&/^[=+@\t\r-]/.test(raw)?"'"+raw:raw;return /[",\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s;}
function exportReport(kind, customRows){let rows,headers,file;
  const inv=customRows||allInvoices();
  if(kind==='Customer Outstanding'){rows=customRows&&customRows[0]?.id?customerRows().filter(x=>customRows.some(i=>i.customer===x.customer)):customerRows();headers=['Customer','Code','Invoices','Invoice Amount','Returns','Payment','TDS','Other Deductions','Credit Days','Overdue','Due','Pending Amount'];rows=rows.map(x=>[x.customer,x.code,x.count,x.invoice,x.returns,x.payment,x.tds,x.ppv+x.pqv+x.ccogs+x.taxd,customerCreditDays(x.customer),x.overdue,x.due,x.pending]);file='customer-outstanding';}
  else if(kind==='Bank Reconciliation'){headers=['Date','Bank Reference','Customer','Advice Reference','Credit Amount','Status'];rows=state.bank.map(x=>[x.date,x.ref,x.customer,x.advice,x.amount,x.status]);file='bank-reconciliation';}
  else if(kind==='Debit Note Register'){headers=['Debit Note','Date','Customer','Invoice','Debit Note Type','Amount','Mapping Status'];rows=state.debitNotes.map(x=>[x.id,x.date,x.customer,x.invoice,x.type||'Unknown',x.amount,x.status]);file='debit-note-register';}
  else if(kind==='Unallocated Transactions'){headers=['Source','Date','Reference','Customer','Type','Amount','Issue'];rows=[...state.advice.filter(x=>!x.invoice).map(x=>['Payment Advice',x.date,x.id,x.customer,x.type,x.amount,'Missing invoice']),...state.bank.filter(x=>x.status==='unmatched').map(x=>['Bank Statement',x.date,x.ref,'','Bank credit',x.amount,'No matching advice'])];file='unallocated-transactions';}
  else if(kind==='Payment Advice'){headers=['Advice Number','Date','Customer','Invoice','Transaction Type','Transaction Description','Amount','Bank Reference / UTR'];rows=state.advice.map(x=>[x.id,x.date,x.customer,x.invoice,x.type,x.description||'',x.amount,x.utr]);file='payment-advice';}
  else if(kind==='Returns'){headers=['Document','Type','Date','Customer','Invoice','Quantity','Amount'];rows=[...state.returns.map(x=>[x.id,'Qty Return',x.date,x.customer,x.invoice,x.qty,x.amount]),...state.priceReturns.map(x=>[x.id,'Price Return',x.date,x.customer,x.invoice,'',x.amount])];file='returns';}
  else if(kind==='Settled Invoices'){headers=['Invoice','Customer','Invoice Date','Invoice Amount','Pending Amount','Status'];rows=allInvoices().filter(x=>x.status==='settled').map(x=>[x.id,x.customer,x.date,x.amount,x.pending,'Fully settled']);file='settled-invoices';}
  else if(kind==='Ageing'){headers=['Invoice','Customer','Invoice Date','Age Days','Invoice Amount','Pending Amount','Age Bucket'];rows=allInvoices().map(x=>[x.id,x.customer,x.date,x.age,x.amount,x.pending,x.age>90?'Over 90':x.age>60?'61-90':x.age>30?'31-60':'0-30']);file='ageing-report';}
  else {headers=['Invoice','Customer','Customer Code','Invoice Date','Credit Days','Due Date','Invoice Amount','Qty Return','Price Return','Payment','TDS','PPV','PQV','CCOGS','TaxD','Round Off','Pending Amount','Status'];rows=inv.map(x=>[x.id,x.customer,x.code,x.date,x.creditDays,x.dueDate,x.amount,x.qtyReturn,x.priceReturn,x.Payment,x.TDS,x.PPV,x.PQV,x.CCOGS,x.TaxD,x.roundOff,x.pending,x.status]);file='invoice-outstanding';}
  const csv=[headers,...rows].map(r=>r.map(csvEscape).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${file}-${today}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast(`${kind} report exported.`);
}
document.getElementById('nav').addEventListener('click',e=>{const btn=e.target.closest('[data-view]');if(btn)go(btn.dataset.view);});
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
render();

if (sharedSession) {
  setInterval(()=>window.refreshWorkspace(true).catch(()=>{}),30000);
  window.addEventListener('focus',()=>window.refreshWorkspace(true).catch(()=>{}));
}

function openBankReceipt(){
  modal('Add bank receipt','Record a cleared bank credit before allocating payment advice.',`<div class="mapping-grid"><label>Bank reference / UTR<input id="bankRef" required /></label><label>Receipt date<input id="bankDate" type="date" value="${today}" /></label><label>Customer (optional)<input id="bankCustomer" /></label><label>Credit amount<input id="bankAmount" type="number" min="0.01" step="0.01" /></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveBank">Save receipt</button>`);
  document.getElementById('saveBank').onclick=async()=>{try{
    const ref=document.getElementById('bankRef').value.trim(),date=document.getElementById('bankDate').value,amount=Number(document.getElementById('bankAmount').value);
    if(!ref||!date||!Number.isFinite(amount)||amount<=0)throw new Error('Reference, date and positive amount are required.');
    if(state.bank.some(row=>row.ref===ref))throw new Error('That bank reference already exists. Review the existing receipt first.');
    state.bank.unshift({ref,date,amount,customer:document.getElementById('bankCustomer').value.trim(),status:'unmatched',advice:''});
    await persist();closeModal();render();showToast('Bank receipt saved. It can now be selected in payment advice.');
  }catch(error){showToast(error.message);}};
}
